/* Validate the nested data that drives turns before accepting a campaign. */
const SaveRules=(()=>{
function validate(s){const ok=(value,message)=>{if(!value)throw Error(message);},integer=(x,min,max)=>Number.isInteger(x)&&x>=min&&x<=max,finite=(x,min,max)=>Number.isFinite(x)&&x>=min&&x<=max,keys=['money','food','wood','metal','cloth'];
ok(s&&Array.isArray(s.countries)&&Array.isArray(s.cells)&&Array.isArray(s.regiments),'Missing campaign data.');
for(const c of s.countries){ok(finite(c.morale,0,100)&&finite(c.progress,0,1e8)&&finite(c.funding,0,100)&&finite(c.militaryBudget,0,200),'Invalid policy or budget.');ok(['agriculture','industry','arms'].every(k=>integer(c.tech?.[k],0,10000)),'Invalid research levels.');ok(keys.every(k=>finite(c.stock?.[k],0,1e12)),'Invalid resources.');}
for(const cell of s.cells){ok(typeof cell.land==='boolean'&&integer(cell.biome?.i,0,255)&&Number.isFinite(cell.elevation)&&integer(cell.population,0,1e9)&&integer(cell.occupation,0,3),'Invalid map cell values.');ok(new Set(cell.buildings).size===cell.buildings.length,'Duplicate cell buildings.');}
for(const r of s.regiments){ok(integer(r.id,1,1e9)&&integer(r.country,0,s.countries.length-1)&&integer(r.cell,0,s.cells.length-1)&&finite(r.supply,0,1e9)&&finite(r.readiness,0,100),'Invalid regiment values.');ok(Object.keys(r.units).length===4&&Object.keys(r.units).every(k=>['infantry','archers','cavalry','artillery'].includes(k)),'Unknown troop type.');ok(r.target===null||integer(r.target,0,s.countries.length-1),'Invalid attack target.');ok(r.previousCell===undefined||integer(r.previousCell,0,s.cells.length-1),'Invalid previous position.');if(r.order)ok(integer(r.order.destination,0,s.cells.length-1)&&integer(r.order.wait,0,2),'Invalid movement order.');}
for(const [key,value] of Object.entries(s.relations)){const ids=key.split('-').map(Number);ok(ids.length===2&&ids[0]<ids[1]&&ids.every(id=>integer(id,0,s.countries.length-1))&&['ally','neutral','enemy'].includes(value),'Invalid treaty relationship.');}
for(const [key,turn] of Object.entries(s.expirations))ok(s.relations[key]!==undefined&&integer(turn,1,1e9),'Invalid treaty expiration.');
ok(new Set(s.proposals.map(p=>p.cell)).size===s.proposals.length,'Duplicate settlement proposal.');for(const p of s.proposals){ok(s.cells[p.cell]?.country===p.country&&!s.cells[p.cell]?.construction,'Invalid settlement proposal location.');if(p.reserved)ok(Object.entries(p.reserved).every(([k,v])=>keys.includes(k)&&finite(v,0,10000)),'Invalid reserved resources.');}
ok(integer(s.nextTrade,1,1e9),'Invalid trade counter.');const trades=[...s.tradeOffers,...s.tradeDeals,...s.shipments];ok(new Set(trades.map(t=>t.id)).size===trades.length&&trades.every(t=>integer(t.id,1,s.nextTrade-1)),'Invalid or duplicate trade identifiers.');for(const d of s.tradeDeals)ok(integer(d.remaining,1,3),'Invalid trade duration.');for(const d of [...s.tradeOffers,...s.tradeDeals])ok(integer(d.from,0,s.countries.length-1)&&integer(d.to,0,s.countries.length-1)&&integer(d.giveQty,1,500)&&integer(d.takeQty,1,500),'Invalid trade quantities.');
return s;}
return {validate};})();
